package alternate;public class QueueCore<E>{private final E[]data;private int head,size;public QueueCore(E[]storage){data=storage;}<U extends E> void put(U value){if(size==data.length){System.out.println("full");return;}data[(head+size++)%data.length]=value;}E get(){if(size==0){System.out.println("empty");return null;}E value=data[head];head=(head+1)%data.length;size--;return value;}}
